  "28": "点击门（目标）⟦0⟧ 上的 <b>∧</b>，门就会分成 ⟦1⟧ 和 ⟦2⟧ 两扇（∧I）。分别将形状对应的钥匙（假设）插入两扇门，即可打开。可以将钥匙拖到门上，或者先点击钥匙再点击门。",
