  "31": "①点击门上的 ∧；②把钥匙 ⟦0⟧ 放到门 ⟦1⟧；③把钥匙 ⟦2⟧ 放到门 ⟦3⟧。",
  "32": "拆开钥匙",
  "33": "如果钥匙的形式为 ⟦0⟧，点击其 <b>∧</b> 即可取出 ⟦1⟧ 与 ⟦2⟧ 两把钥匙（∧E）。取出的虚线钥匙可用于当前门及由此分出的所有门。",
  "34": "原来的钥匙 ⟦0⟧ 无法直接打开门 ⟦1⟧ 或门 ⟦2⟧。",
  "35": "点击钥匙上的 ∧ 使用 ∧E；点击门上的 ∧ 使用 ∧I。",
  "36": "①点击钥匙上的 ∧；②点击门上的 ∧；③把钥匙 ⟦0⟧ 放到门 ⟦1⟧；④把钥匙 ⟦2⟧ 放到门 ⟦3⟧。若先拆分门，每扇分出的门都需要重新拆开钥匙。",
  "37": "点击一次钥匙上的 ∧，证明树中会出现两次 ∧E。游戏的一步操作不一定对应一次推理规则的应用。",
  "38": "新的房间",
