  "861": "三阶循环群 ℤ/3（3 个元素）",
  "862": "模 3 加法。元素 1、2、3 分别代表 0、1、2。",
  "863": "克莱因四元群",
  "864": "4 个元素的交换群，每个元素的平方都等于单位元（元素 1）。",
  "865": "对称群 S₃",
  "866": "6 个元素：集合 {1,2,3} 的全部置换。元素 1 为恒等置换，2 为 (1 2)，3 为 (1 3)，4 为 (2 3)，5 为 (1 2 3)，6 为 (1 3 2)。本群不交换。",
  "867": "三元素链",
