  "869": "菱形偏序",
  "870": "4 个元素。1 为最小元，4 为最大元，2 和 3 不可比较。",
  "871": "已加载“⟦0⟧”。现在可以自由修改各个表。",
  "872": "⟦0⟧ 对每个个体 ⟦1⟧ 都为真",
