  "895": "反例之层：第 ⟦0⟧ 层（所有假设亮起，唯独目标不亮）",
  "896": "关键所在",
  "897": "从 0 逐级上升，在第 ⟦0⟧ 层之后又回到第 ⟦1⟧ 层的塔",
  "898": "两条法则切断了返回的阶梯，使楼梯无限延伸的塔",
  "899": "0 不是任何数的后继",
  "900": "若后继相等，则原数相等",
  "901": "法则和归纳法都得到遵守。即便如此，这座塔仍有顶层。",
  "902": "从 0 开始，每次沿后继运算 s 向上一层，阶梯最终会回到已经走过的楼层。若模型中的个体数有限，任何模型都会呈现这种循环。",
  "903": "塔顶并不存在。",
  "904": "“0 不是任何数的后继”切断了通向 0 的回路；“若后继相等，则原数相等”则排除了在中途并入旧楼层的路径。由于没有返回的阶梯，这座塔只能无限向上延伸。",
  "905": "⟦0⟧ 已超出作用域",
  "906": "仍有未完成的证明空位",
