  "2068": "⟦0⟧⟦1⟧⟦2⟧点击“全部设为未定”可恢复初始状态。确定各原子式的真值后，右侧将依次计算复合公式。只要所有前提为真而目标为假，就得到了反例。",
  "2069": "谓词表初始为未知；每次点击依次切换：假 → 真 → 假……",
