  "2077": "<button type=\"button\" class=\"btn small primary\" data-cmd=\"refuteDone\">反例已完成！</button>",
  "2078": "<button type=\"button\" class=\"lamp⟦0⟧\" data-tv=\"⟦1⟧\" aria-label=\"⟦2⟧ 为 ⟦3⟧\"><i class=\"at\">⟦4⟧</i><span class=\"tv\">⟦5⟧</span></button>",
  "2079": "⟦0⟧ 仍未确定",
  "2080": "已将 ⟦0⟧ 赋值为 ⟦1⟧",
  "2081": "<h3 class=\"ev-title\">该赋值下的求值结果</h3>⟦0⟧⟦1⟧",
  "2082": "点击按钮为原子命题赋值，右侧的求值结果会随之确定。",
