  "3190": "Lean 模式：关闭",
  "3191": "无限制模式：开启（所有层均可游玩）",
  "3192": "无限制模式：关闭（通关上一层后解锁下一层）",
  "3193": "<h2>重置游戏进度？</h2>\n        <p>以下记录将全部清除。 <b>此操作无法撤销。</b></p>\n        <ul class=\"help-list\"><li>各关卡通关记录与最佳步数</li><li>已获得的定理卡片</li><li>已阅读的引导、教程与帮助页面（“新”标记和首次引导将重新出现）</li></ul>\n        <label class=\"reset-prefs\"><input type=\"checkbox\" id=\"resetPrefs\" checked> 同时将开关恢复默认设置</label>\n        <p class=\"note\">默认设置仅开启“剧情” (“显示证明项（λ 项）”“Lean 模式”“无限制模式”“自行选择名字”和“通关后自动回放”均关闭, 亮度为“自动”). 当前语言设置会保留。 如果同时重置设置，页面会重新加载。</p>\n        <div class=\"actions\"><button class=\"btn\" type=\"button\" data-cmd=\"close\">取消</button><button class=\"btn danger\" type=\"button\" data-cmd=\"resetDo\">重置</button></div>",
  "3194": "已重置全部进度。",
  "3195": "⟦0⟧：⟦1⟧",
  "3196": "本大厅的公理不含数学归纳法。没有归纳法，也许无法打开这扇门。",
  "3197": "已退回进入死路之前。",
